<?php
declare(strict_types=1);require __DIR__.'/_init.php';try{if($_SERVER['REQUEST_METHOD']==='GET'){json_response(true,$pdo->query('SELECT i.id,i.sku,i.name,i.unit,i.reorder_level,i.reorder_qty,i.unit_cost,c.name category,s.name supplier,COALESCE(v.available_qty,0) available_qty FROM items i LEFT JOIN categories c ON c.id=i.category_id LEFT JOIN suppliers s ON s.id=i.preferred_supplier_id LEFT JOIN v_item_availability v ON v.item_id=i.id WHERE i.is_active=1 ORDER BY i.name')->fetchAll());}require_role(['admin']);$d=request_json();$type=(string)($d['type']??'');$batch=positive_int($d['batch_id']??null,'batch_id');$warehouse=positive_int($d['warehouse_id']??null,'warehouse_id');$qty=positive_int($d['quantity']??null);$reason=trim((string)($d['reason']??''));if($reason==='')json_response(false,null,'VALIDATION_ERROR','Reason is required.',['reason'=>'Required'],422);$delta=match($type){'receive'=>$qty,'issue'=>-$qty,'write_off'=>-$qty,'adjust'=>(int)($d['delta']??0),default=>0};if(!$delta)json_response(false,null,'VALIDATION_ERROR','Unsupported movement type.',['type'=>'Invalid'],422);$pdo->beginTransaction();try{if(in_array($type,['issue','write_off'],true)){$q=$pdo->prepare('SELECT b.expiration_date FROM batches b WHERE b.id=?');$q->execute([$batch]);$exp=$q->fetchColumn();if($type==='issue'&&$exp<date('Y-m-d'))throw new DomainException('Expired batches cannot be issued.');} $balance=InventoryService::move($pdo,$batch,$warehouse,$delta,$type,$reason,(int)$user['id']);$pdo->commit();json_response(true,['balance_after'=>$balance]);}catch(Throwable $e){$pdo->rollBack();throw $e;}}catch(DomainException $e){json_response(false,null,'STOCK_REJECTED',$e->getMessage(),[],422);}catch(Throwable $e){api_error($e);}
